-- idx58 [Thyroid & Parathyroid] differentiate -> easy skill2 ans=D
UPDATE questions SET
  question_text = 'A researcher notes that the thyroid follicular cells of a healthy adult release predominantly a hormone carrying four iodine atoms. However, this circulating hormone is only weakly active, and inside peripheral tissues such as the liver and kidney an enzyme removes a single iodine atom to generate the form that binds nuclear receptors most strongly and drives cellular metabolism. Which hormone is produced by this enzymatic conversion in the target tissues?',
  options = '[{"label": "A", "text": "Thyroxine"}, {"label": "B", "text": "Thyroid-stimulating hormone"}, {"label": "C", "text": "Calcitonin"}, {"label": "D", "text": "Triiodothyronine"}]'::jsonb,
  correct_answer = 'D',
  explanation = 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the thyroid secretes mostly thyroxine (T4), which carries four iodine atoms and is relatively weak; peripheral deiodinase enzymes remove one iodine atom to form triiodothyronine (T3), the more metabolically active hormone that binds thyroid hormone receptors with far greater affinity. (Choice D) is correct: T3 (triiodothyronine) has three iodine atoms and is the product of removing one iodine from T4; it is several times more potent than T4 and is the principal form acting on target cells. (Choice A) is incorrect: Thyroxine (T4) is the four-iodine hormone actually secreted and described in the stem as weakly active — it is the substrate for the conversion, not its product. (Choice B) is incorrect: Thyroid-stimulating hormone is a pituitary glycoprotein that stimulates the thyroid to make and release thyroid hormones; it is not an iodinated hormone and is not made by deiodination in peripheral tissues. (Choice C) is incorrect: Calcitonin is a peptide hormone from the thyroid''s parafollicular (C) cells that lowers blood calcium; it contains no iodine and is unrelated to metabolic rate or deiodinase activity. This item exercises the skill of tracing a hormone''s peripheral activation pathway rather than matching vocabulary in the stem.',
  difficulty = 'easy',
  cognitive_skill = 2,
  estimated_time_seconds = 70
WHERE id = '1180cc2b-7108-4b51-9a34-ab2c6d7bff25';
DELETE FROM question_distractor_metadata WHERE question_id = '1180cc2b-7108-4b51-9a34-ab2c6d7bff25';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('1180cc2b-7108-4b51-9a34-ab2c6d7bff25', 'A', 'partial_truth', 'Substrate mistaken for product (names the secreted T4 that the stem describes rather than its more active conversion product)'),
  ('1180cc2b-7108-4b51-9a34-ab2c6d7bff25', 'B', 'adjacent_fact', 'Wrong axis level (pituitary tropic hormone that regulates the thyroid, not an iodinated hormone made by peripheral deiodination)'),
  ('1180cc2b-7108-4b51-9a34-ab2c6d7bff25', 'C', 'adjacent_fact', 'Same-gland, wrong-function hormone (thyroid C-cell calcium hormone, non-iodinated and unrelated to metabolic activation)');

-- idx92 [Gonads, Pineal & Other Tissues] differentiate -> medium skill2 ans=D
UPDATE questions SET
  question_text = 'A climber who has lived for several weeks at 4,500 m develops a rising erythrocyte count. Interstitial cells of her kidneys, sensing the persistently low oxygen tension, release a peptide hormone into the circulation. This hormone must reach a specific target tissue to produce the increase in oxygen-carrying capacity. On which tissue does the hormone act, and what does it do there?',
  options = '[{"label": "A", "text": "It acts on the spleen, slowing the removal of aging erythrocytes from circulation"}, {"label": "B", "text": "It acts on the liver, stimulating hepatocytes to synthesize additional hemoglobin"}, {"label": "C", "text": "It acts on the kidney tubules, increasing the reabsorption of filtered iron"}, {"label": "D", "text": "It acts on the red bone marrow, driving progenitor cells to mature into additional erythrocytes"}]'::jsonb,
  correct_answer = 'D',
  explanation = 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the hormone described is erythropoietin (EPO), and its principal action is on the red bone marrow, where it stimulates erythroid progenitor cells to proliferate and differentiate into mature erythrocytes, thereby raising the blood''s oxygen-carrying capacity. (Choice D) is correct: EPO travels from the kidney to the red (hematopoietic) bone marrow, where it binds receptors on committed erythroid progenitor cells and promotes their survival, proliferation, and maturation into red blood cells; more erythrocytes means more hemoglobin available to carry oxygen, which is the adaptive response to chronic hypoxia. (Choice A) is incorrect: the spleen is a site of erythrocyte destruction and recycling, but EPO does not act there to prolong red-cell lifespan; the adaptive rise in red-cell number is driven by increased production in marrow, not by slowed destruction in the spleen. (Choice B) is incorrect: hemoglobin is synthesized inside developing erythrocytes in the marrow, not manufactured by hepatocytes and exported; the liver is not the target of EPO, and EPO''s effect is to increase erythrocyte number rather than to have another organ mass-produce free hemoglobin. (Choice C) is incorrect: although the kidney is the source of EPO, EPO is not a hormone that acts back on the renal tubules, and iron reabsorption there is not its mechanism; confusing the organ that secretes the hormone with the organ it targets is the trap. This item exercises the skill of distinguishing an endocrine hormone''s target tissue and action from its site of secretion.',
  difficulty = 'medium',
  cognitive_skill = 2,
  estimated_time_seconds = 75
WHERE id = '8877fcaf-e89a-43b4-bc04-4a5b5e1b643b';
DELETE FROM question_distractor_metadata WHERE question_id = '8877fcaf-e89a-43b4-bc04-4a5b5e1b643b';
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype) VALUES
  ('8877fcaf-e89a-43b4-bc04-4a5b5e1b643b', 'A', 'adjacent_fact', 'spleen as site of erythrocyte destruction confused with an EPO target'),
  ('8877fcaf-e89a-43b4-bc04-4a5b5e1b643b', 'B', 'misconception', 'liver/hepatocytes imagined to mass-produce free hemoglobin instead of marrow making red cells'),
  ('8877fcaf-e89a-43b4-bc04-4a5b5e1b643b', 'C', 'reversed_relationship', 'source organ (kidney) mistaken for the target organ of its own hormone');

COMMIT;
